<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useQuasar } from 'quasar'
import LineChart from './LineChart.vue'
const $q=useQuasar()
let dismissNotice:(()=>void)|undefined
function notice(type:'positive'|'negative',message:string){dismissNotice?.();dismissNotice=$q.notify({type,message,position:'top-right',timeout:type==='negative'?6000:2500})}
const pages=['儀表板','行情與資料','策略與提案','模擬帳戶','回測實驗室','風控與監察','研究中心','設定']
const page=ref('儀表板'),token=ref(sessionStorage.getItem('tradinglab-token')||''),login=ref(!token.value),busy=ref(false),error=ref(''),state=ref<any>(null),bars=ref<any[]>([]),symbol=ref('0050'),dataset=ref(''),csv=ref(''),source=ref('使用者匯入 CSV'),adjusted=ref(false),month=ref('20250101'),result=ref<any>(null),selectedJob=ref(''),signal=ref<any>(null),unlock=ref(''),rules=ref<any>(null)
const marketBars=ref<any[]>([]);let marketDataset='';
const order=ref({symbol:'0050',side:'BUY',quantity:50,price:40,unit:'ODD',reason:'人工研究提案',model_id:null as string|null})
const bt=ref({start:'',end:'',strategy:'trend',fast:5,slow:20})
const schedule=ref({enabled:false,interval:3600})
const money=(n:any)=>n==null?'N/A':new Intl.NumberFormat('zh-TW',{maximumFractionDigits:2}).format(n)
const percent=(n:any)=>n==null?'N/A':(n*100).toFixed(2)+'%'
const time=(n:number)=>new Date(n*1000).toLocaleString('zh-TW',{hour12:false})
const currentQuote=computed(()=>state.value?.quotes.find((q:any)=>q.symbol===symbol.value))
const datasetOptions=computed(()=>state.value?.datasets.map((d:any)=>({label:`${d.symbol} · ${d.source} · ${d.metadata.rows} 日`,value:d.id}))||[])
const jobResult=computed(()=>result.value?.result)
const statusNames:Record<string,string>={PROPOSED:'提案',RISK_REJECTED:'風控拒絕',APPROVED:'待人工確認',SENT:'已送出',ACCEPTED:'已受理',PARTIAL:'部分成交',FILLED:'全部成交',CANCELLED:'已撤單',FAILED:'失敗',UNKNOWN:'狀態未知',QUEUED:'排隊中',RUNNING:'執行中',COMPLETED:'完成',SKIPPED:'已跳過'}
async function api(path:string,body?:unknown,headers:Record<string,string>={}){
 const response=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token.value,...(body===undefined?{}:{'Content-Type':'application/json'}),...headers},body:body===undefined?undefined:JSON.stringify(body)})
 const value=await response.json();if(!response.ok){if(response.status===401)login.value=true;throw new Error(typeof value.detail==='string'?value.detail:JSON.stringify(value.detail))}return value
}
async function refresh(){try{state.value=await api('/state');const activeId=state.value.active[symbol.value]?.dataset;if(activeId&&marketDataset!==activeId){marketDataset=activeId;marketBars.value=await api('/bars/'+activeId)};if(!dataset.value){dataset.value=state.value.active[symbol.value]?.dataset||state.value.datasets[0]?.id;await loadBars();if(currentQuote.value)order.value.price=Math.floor(currentQuote.value.close*1.02*20)/20}if(!rules.value){rules.value=Object.fromEntries(['per_order','per_symbol','total','daily_loss','drawdown','daily_proposals','fee_rate','min_fee','slippage','participation'].map(k=>[k,state.value.rules[k]]));schedule.value={enabled:state.value.schedule.enabled,interval:state.value.schedule.interval}}
 if(selectedJob.value)result.value=await api('/jobs/'+selectedJob.value)
 }catch(e:any){error.value=e.message}}
async function act(fn:()=>Promise<any>,message='已完成'){busy.value=true;error.value='';try{const v=await fn();notice('positive',message);await refresh();return v}catch(e:any){error.value=e.message;notice('negative',e.message)}finally{busy.value=false}}
async function connect(){sessionStorage.setItem('tradinglab-token',token.value);await refresh();if(state.value)login.value=false}
async function loadBars(){if(dataset.value)bars.value=await api('/bars/'+dataset.value)}
async function changeSymbol(){dataset.value=state.value.active[symbol.value]?.dataset||dataset.value;order.value.symbol=symbol.value;await loadBars();if(currentQuote.value)order.value.price=Math.floor(currentQuote.value.close*1.01*20)/20}
async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file)csv.value=await file.text()}
async function importData(){await act(async()=>{const r=await api('/data/import',{symbol:symbol.value,csv:csv.value,source:source.value,adjusted:adjusted.value});dataset.value=r.dataset;await loadBars();return r},'CSV 已通過品質檢查並保存')}
async function submit(){await act(()=>api('/proposals',order.value,{'Idempotency-Key':crypto.randomUUID()}),'提案已送獨立風控審核');page.value='策略與提案'}
async function control(action:string,enabled=true,reason=''){await act(()=>api('/control',{action,enabled,reason}))}
async function startJob(kind:string){await act(async()=>{const j=await api('/jobs',{kind,dataset:dataset.value,...bt.value});selectedJob.value=j.id;result.value=await api('/jobs/'+j.id)},'工作已提交；相同資料與參數會去重')}
async function viewJob(id:string){selectedJob.value=id;await act(async()=>{result.value=await api('/jobs/'+id)},'已載入工作紀錄')}
async function getSignal(){await act(async()=>{signal.value=await api('/strategy/'+symbol.value)},'已計算研究訊號')}
function useSignal(){if(signal.value?.signal==='HOLD')return;order.value={symbol:symbol.value,side:signal.value.signal,quantity:signal.value.quantity,price:signal.value.price,unit:'ODD',reason:signal.value.reason,model_id:signal.value.model_id||null}}
function reduce(p:any){order.value={symbol:p.symbol,side:'SELL',quantity:Math.min(999,p.quantity),price:Math.floor(p.price*.98*20)/20,unit:'ODD',reason:'人工模擬減倉／平倉',model_id:null};page.value='策略與提案'}
let timer:ReturnType<typeof setInterval>
onMounted(async()=>{if(token.value)await refresh();timer=setInterval(()=>{if(token.value&&!login.value&&!busy.value)void refresh()},3000)})
onUnmounted(()=>clearInterval(timer))
</script>

<template>
<div class="app-shell">
 <aside class="sidebar"><div class="brand"><span class="brand-mark">T<span>↗</span></span><div>TradingLab<small>策略研究工作室</small></div></div>
 <div class="nav-caption">WORKSPACE / 研究工作區</div><nav><button v-for="(p,i) in pages" :key="p" :aria-label="p" :class="{active:page===p}" @click="page=p"><span class="nav-index">0{{i+1}}</span>{{p}}<span v-if="page===p" class="nav-dot">●</span></button></nav>
 <div class="sidebar-bottom"><div class="small-label">LOCAL SIMULATION</div><p>把假設留給研究，<br>把界線交給風控。</p><div class="local"><span>●</span> 僅本機 · LIVE 未開放</div><button class="token-link" @click="login=true">管理本機存取權杖</button></div></aside>
 <main><header><div class="breadcrumb">研究工作區 <span>/</span> {{page}}</div><div class="header-right"><span class="mode-pill">{{state?.mode||'離線'}} <span>模擬環境</span></span><span class="avatar">TL</span></div></header>
 <div class="content"><div class="page-heading"><div><div class="eyebrow">TRADING LAB / {{String(pages.indexOf(page)+1).padStart(2,'0')}}</div><h1>{{page}}</h1><p>{{page==='儀表板'?'觀察市場、驗證假設。每一筆委託都有可追溯的依據。':'以可重現資料與明確假設，完成你的研究流程。'}}</p></div><q-btn v-if="state" outline color="primary" label="重新整理" :loading="busy" @click="refresh"/></div>
 <div class="notice"><span class="notice-tag">{{state?.mode||'DEMO'}}</span><span>{{state?.mode==='REPLAY'?'歷史日線重播，非即時行情。':'固定 seed 合成行情，不代表真實市場。'}} 無獲利承諾；模擬採即時交割，與真實市場不同。</span></div>
 <div v-if="error" class="error" role="alert">{{error}}</div>
 <div v-if="!state" class="panel empty">{{login?'請輸入本機存取權杖以連接服務。':'正在連接本機服務…'}}<q-btn flat label="連接服務" @click="login=true"/></div>
 <template v-else>
 <div v-if="state.locked" class="error">交易鎖定已持久保存。請至「風控與監察」檢查證據；重新啟動不會解除。</div>
 <template v-if="page==='儀表板'">
 <div class="metrics"><div class="metric featured"><div>模擬帳戶淨值 <span>NTD</span></div><strong>{{money(state.account.nav)}}</strong><small>初始資金 NT$100,000</small></div><div class="metric"><div>可用現金</div><strong>{{money(state.account.available)}}</strong><small>現金 {{money(state.account.cash)}}</small></div><div class="metric"><div>持倉曝險</div><strong>{{percent(state.account.exposure/state.account.nav)}}</strong><small>上限 {{percent(state.rules.total)}} · {{state.account.positions.length}} 檔標的</small></div><div class="metric"><div>目前回撤</div><strong>{{percent(state.account.drawdown)}}</strong><small>保留資金 NT$ {{money(state.account.reserved)}}</small></div></div>
 <div class="two-column"><section class="panel"><div class="panel-title"><h2>行情觀測</h2><q-select dense outlined v-model="symbol" :options="Object.keys(state.active)" @update:model-value="changeSymbol"/></div><div class="quote-price">{{money(currentQuote?.close)}} <small>TWD / 股</small></div><LineChart :values="marketBars.slice(0,state.cursor+1).map(b=>b.close)" :labels="marketBars.slice(0,state.cursor+1).map(b=>b.date)"/><div class="chart-footer"><span>{{currentQuote?.source}}</span><span>日線 · 虛擬日期 {{state.virtual_date}}</span></div></section>
 <section class="panel"><div class="panel-title"><h2>服務與防線</h2><span class="badge">同機程序隔離</span></div><div v-for="name in ['backend','risk','watchdog','research']" :key="name" class="service"><div><strong>{{({backend:'策略與交易後端',risk:'獨立風控服務',watchdog:'監察程序',research:'研究工作程序'} as any)[name]}}</strong><small>{{name}}</small></div><span :class="['service-state',state.server_time-(state.heartbeats.find((h:any)=>h.service===name)?.time||0)<15?'healthy':'unhealthy']">{{state.server_time-(state.heartbeats.find((h:any)=>h.service===name)?.time||0)<15?'● 運作中':'● 心跳過期'}}</span></div><div class="guard-status">新增風險 <strong>{{state.locked||state.stop_risk?'已停止':'受風控保護'}}</strong></div></section></div>
 <section class="panel replay-strip"><div><div class="eyebrow">VIRTUAL CLOCK</div><h2>{{state.virtual_date}} <span>第 {{state.cursor+1}} 個交易時點</span></h2><p>推進到資料內下一交易日，嘗試以開盤價加滑價成交。</p></div><q-btn color="primary" label="推進一個交易日 →" :loading="busy" @click="act(()=>api('/replay/step',{}),'虛擬時鐘已推進')"/></section>
 <section class="panel"><div class="panel-title"><h2>目前持倉</h2><span class="muted">股數，不是張數</span></div><div v-if="!state.account.positions.length" class="empty">尚無持倉。前往策略與提案，建立第一筆模擬委託。</div><table v-else><thead><tr><th>標的</th><th>股數</th><th>平均成本</th><th>市值</th><th>未實現損益</th></tr></thead><tbody><tr v-for="p in state.account.positions" :key="p.symbol"><td>{{p.symbol}}</td><td>{{p.quantity}}</td><td>{{money(p.cost)}}</td><td>{{money(p.value)}}</td><td>{{money(p.unrealized)}}</td></tr></tbody></table></section>
 </template>
 <template v-if="page==='行情與資料'">
 <section class="panel"><div class="panel-title"><h2>資料集瀏覽</h2><span class="badge">Asia/Taipei · 日線</span></div><q-select outlined v-model="dataset" :options="datasetOptions" emit-value map-options label="選擇資料集" @update:model-value="loadBars"/><LineChart :values="bars.map(b=>b.close)" :labels="bars.map(b=>b.date)"/><div class="info-grid" v-for="d in state.datasets.filter((d:any)=>d.id===dataset)" :key="d.id"><p><b>來源</b>{{d.source}}</p><p><b>資料時間</b>{{d.metadata.start}} → {{d.metadata.end}}</p><p><b>接收時間</b>{{time(d.received)}}</p><p><b>價格處理</b>{{d.metadata.adjusted?'還原價格（僅供研究）':'原始／未還原價格'}}</p><p><b>限制</b>{{d.metadata.corporate_actions}}</p><p><b>交易日曆</b>{{d.metadata.calendar}}</p></div><q-btn outline color="primary" label="啟用此資料集重播" :loading="busy" @click="act(()=>api('/data/activate',{dataset}),'已啟用並重設虛擬時鐘')"/></section>
 <div class="two-column"><section class="panel"><h2>匯入 OHLCV CSV</h2><p class="muted">date,open,high,low,close,volume；日期 YYYY-MM-DD，成交量以股為單位。</p><div class="form-grid"><q-select outlined v-model="symbol" :options="Object.keys(state.rules.whitelist)" label="標的"/><q-input outlined v-model="source" label="資料來源名稱"/></div><input type="file" accept=".csv,text/csv" aria-label="CSV 檔案" @change="readFile"/><q-input outlined v-model="csv" type="textarea" label="CSV 內容" rows="5"/><q-checkbox v-model="adjusted" label="這是還原價格（禁止用於委託）"/><q-btn color="primary" label="檢查並匯入" :disable="!csv" :loading="busy" @click="importData"/></section><section class="panel"><h2>TWSE 公開日線</h2><p class="muted">按月份下載並快取，最短請求間隔 10 秒。不提供即時 PAPER 行情。</p><q-input outlined v-model="month" label="月份 YYYYMM01"/><q-select outlined v-model="symbol" :options="Object.keys(state.rules.whitelist)" label="標的"/><q-btn outline color="primary" label="取得公開日線" :loading="busy" @click="act(()=>api('/data/twse',{symbol,month}),'已保存公開日線')"/><div class="hint">外部服務失敗會顯示原因，不會自動改用合成資料。</div></section></div>
 </template>
 <template v-if="page==='策略與提案'">
 <div class="two-column"><section class="panel"><div class="panel-title"><h2>研究訊號</h2><span class="badge">{{state.active_model?'候選模型':'MA5 / MA20 拉回策略'}}</span></div><p>MA5 高於 MA20 且當日收盤下跌時提出買進；MA5 低於 MA20 時提出賣出。已有持倉不攤平加碼。</p><q-select outlined v-model="symbol" :options="Object.keys(state.active)" label="標的"/><q-btn outline color="primary" label="計算目前訊號" :loading="busy" @click="getSignal"/><div v-if="signal" class="hint"><strong>{{signal.signal}}</strong><p>{{signal.reason}}</p><p v-if="signal.quantity">目標 {{signal.quantity}} 股 · 估計手續費 {{money(signal.estimated_fee)}}</p><q-btn flat label="帶入提案表單" :disable="signal.signal==='HOLD'" @click="useSignal"/></div></section>
 <section class="panel"><h2>建立人工模擬提案</h2><div class="form-grid"><q-select outlined v-model="order.symbol" :options="Object.keys(state.active)" label="標的"/><q-select outlined v-model="order.side" :options="['BUY','SELL']" label="買賣方向"/><q-input outlined type="number" v-model.number="order.quantity" label="數量（股）"/><q-input outlined type="number" step="0.01" v-model.number="order.price" label="限價（TWD）"/><q-select outlined v-model="order.unit" :options="[{label:'零股 1–999 股',value:'ODD'},{label:'整股 1,000 股倍數',value:'BOARD'}]" emit-value map-options label="交易單位"/><q-input outlined v-model="order.reason" label="提案原因"/></div><div class="hint">估計委託金額 NT$ {{money(order.price*order.quantity)}}；買進上限 {{percent(state.rules.per_order)}} 淨值。需風控核准後再人工確認。</div><q-btn color="primary" label="送出風控審核" :loading="busy" @click="submit"/></section></div>
 </template>
 <template v-if="page==='模擬帳戶'"><div class="metrics"><div class="metric"><div>現金</div><strong>{{money(state.account.cash)}}</strong></div><div class="metric"><div>保留資金</div><strong>{{money(state.account.reserved)}}</strong></div><div class="metric"><div>可用現金</div><strong>{{money(state.account.available)}}</strong></div></div><section class="panel"><h2>持倉與模擬減倉</h2><p>{{state.account.settlement}}</p><table><thead><tr><th>標的</th><th>股數</th><th>平均成本</th><th>未實現損益</th><th>操作</th></tr></thead><tbody><tr v-for="p in state.account.positions" :key="p.symbol"><td>{{p.symbol}}</td><td>{{p.quantity}}</td><td>{{money(p.cost)}}</td><td>{{money(p.unrealized)}}</td><td><q-btn flat color="primary" label="準備減倉提案" @click="reduce(p)"/></td></tr></tbody></table><div v-if="!state.account.positions.length" class="empty">目前沒有持倉</div></section></template>
 <section v-if="['策略與提案','模擬帳戶'].includes(page)" class="panel"><div class="panel-title"><h2>委託與風控決策</h2><span class="muted">核准有效 {{state.rules.approval_ttl}} 秒</span></div><div class="table-scroll"><table><thead><tr><th>標的 / 方向</th><th>數量 / 已成交</th><th>限價</th><th>狀態</th><th>風控理由</th><th>操作</th></tr></thead><tbody><tr v-for="o in state.orders" :key="o.id"><td>{{o.payload.symbol}} <span class="badge">{{o.payload.side}}</span></td><td>{{o.payload.quantity}} / {{o.filled}}</td><td>{{money(o.payload.price)}}</td><td>{{statusNames[o.status]}}</td><td class="reason">{{o.reason}}<small>規則 v{{o.rule_version||'—'}} · {{o.id.slice(0,8)}}</small></td><td><q-btn v-if="o.status==='APPROVED'" dense color="primary" label="確認模擬委託" :loading="busy" @click="act(()=>api('/orders/'+o.id+'/execute',{}),'已受理，等待下一重播開盤')"/><q-btn v-if="['APPROVED','ACCEPTED','PARTIAL'].includes(o.status)" flat dense label="撤單" @click="act(()=>api('/orders/'+o.id+'/cancel',{}),'已撤單並釋放保留資金')"/><q-btn v-if="['UNKNOWN','SENT'].includes(o.status)" flat label="核對狀態" @click="act(()=>api('/orders/'+o.id+'/reconcile',{}))"/></td></tr></tbody></table></div><div v-if="!state.orders.length" class="empty">尚無提案</div></section>
 <section v-if="page==='模擬帳戶'" class="panel"><h2>模擬成交紀錄</h2><table><thead><tr><th>標的 / 方向</th><th>股數</th><th>成交價</th><th>手續費</th><th>交易稅</th><th>重播索引</th></tr></thead><tbody><tr v-for="f in state.fills" :key="f.id"><td>{{f.symbol}} / {{f.side}}</td><td>{{f.quantity}}</td><td>{{money(f.price)}}</td><td>{{money(f.fee)}}</td><td>{{money(f.tax)}}</td><td>{{f.bar}}</td></tr></tbody></table><div v-if="!state.fills.length" class="empty">尚無成交；已受理委託需推進重播日期。</div></section>
 <template v-if="page==='回測實驗室'"><section class="panel"><h2>建立回測實驗</h2><q-select outlined v-model="dataset" :options="datasetOptions" emit-value map-options label="標的與資料版本"/><div class="form-grid"><q-input outlined v-model="bt.start" type="date" label="開始日期（空白使用全部）" stack-label/><q-input outlined v-model="bt.end" type="date" label="結束日期" stack-label/><q-select outlined v-model="bt.strategy" :options="[{label:'趨勢拉回 MA',value:'trend'},{label:'買進持有',value:'hold'}]" emit-value map-options label="策略"/><q-input outlined v-model.number="bt.fast" type="number" label="快速均線"/><q-input outlined v-model.number="bt.slow" type="number" label="慢速均線"/></div><p class="muted">成本使用規則 v{{state.rules.version}}：手續費 {{percent(state.rules.fee_rate)}}，最低 {{state.rules.min_fee}} 元，滑價 {{percent(state.rules.slippage)}}。可在設定頁調整後建立新實驗。</p><q-btn color="primary" label="執行回測" :loading="busy" @click="startJob('backtest')"/></section>
 <section v-if="jobResult?.strategy" class="panel"><div class="panel-title"><h2>回測結果</h2><span>實線：策略 · 虛線：買進持有</span></div><LineChart :values="jobResult.strategy.curve.map((c:any)=>c.nav)" :secondary="jobResult.benchmark.curve.map((c:any)=>c.nav)" :labels="jobResult.strategy.curve.map((c:any)=>c.date)"/><table><thead><tr><th>指標</th><th>策略</th><th>基準（相同投入與成本）</th></tr></thead><tbody><tr v-for="(label,key) in {net_return:'扣費後報酬',gross_return:'扣費前報酬（含滑價）',max_drawdown:'最大回撤',win_rate:'已平倉勝率',average_win:'平均獲利',average_loss:'平均虧損',profit_factor:'Profit factor',trade_count:'交易次數',closed_trades:'已平倉筆數',exposure:'平均曝險',turnover:'換手率',costs:'費用與稅合計',open_quantity:'期末未平倉股數'}" :key="key"><td>{{label}}</td><td>{{['net_return','gross_return','max_drawdown','win_rate','exposure','turnover'].includes(key)?percent(jobResult.strategy.metrics[key]):money(jobResult.strategy.metrics[key])}}</td><td>{{['net_return','gross_return','max_drawdown','win_rate','exposure','turnover'].includes(key)?percent(jobResult.benchmark.metrics[key]):money(jobResult.benchmark.metrics[key])}}</td></tr></tbody></table><p v-for="w in jobResult.strategy.warnings.filter(Boolean)" :key="w" class="hint">{{w}}</p><details><summary>查看完整交易清單</summary><pre>{{JSON.stringify(jobResult.strategy.trades,null,2)}}</pre></details></section></template>
 <template v-if="page==='風控與監察'"><section class="panel"><div class="panel-title"><h2>獨立操作邊界</h2><span class="badge">規則 v{{state.rules.version}}</span></div><div class="control-grid"><div><h3>策略提案</h3><p>只控制策略產生訊號。</p><q-btn outline :label="state.pause_strategy?'恢復策略':'暫停策略'" @click="control('pause_strategy',!state.pause_strategy)"/></div><div><h3>新增風險</h3><p>停止買進，不等於平倉。</p><q-btn outline :label="state.stop_risk?'恢復新增風險':'停止新增風險'" @click="control('stop_risk',!state.stop_risk)"/></div><div><h3>未成交委託</h3><p>撤單並釋放未成交保留額度。</p><q-btn outline label="撤銷全部未成交委託" @click="control('cancel_all')"/></div><div><h3>模擬減倉</h3><p>先確認部位，再建立賣出提案。</p><q-btn outline label="檢視持倉" @click="page='模擬帳戶'"/></div></div></section><section class="panel"><h2>告警與證據</h2><div v-if="!state.alerts.length" class="empty">目前沒有告警</div><div class="alert-row" v-for="a in state.alerts" :key="a.id"><div><span :class="['badge',a.severity==='CRITICAL'?'danger':'']">{{a.severity}}</span> <strong>{{a.code}}</strong><small>{{time(a.time)}}</small><pre>{{a.evidence}}</pre></div><q-btn flat :disable="!!a.acknowledged" :label="a.acknowledged?'已確認':'確認告警'" @click="act(()=>api('/alerts/'+a.id+'/ack',{}))"/></div><q-input outlined v-model="unlock" label="人工檢查與解除鎖定紀錄（至少 8 字）"/><q-btn outline color="negative" label="檢查並解除持久鎖定" :disable="!state.locked" @click="control('unlock',true,unlock)"/></section><section class="panel"><h2>稽核紀錄（最近 100 筆）</h2><p class="muted">Append-only 應用介面與雜湊鏈；同機管理者仍可修改檔案，不保證絕對防竄改。</p><details v-for="a in state.audit" :key="a.id"><summary>#{{a.id}} · {{JSON.parse(a.body).kind}} · {{time(JSON.parse(a.body).time)}}</summary><pre>{{a.body}}</pre><small>{{a.hash}}</small></details></section></template>
 <template v-if="page==='研究中心'"><section class="panel"><div class="panel-title"><h2>批次候選模型研究</h2><span class="badge">Logistic regression · seed 42</span></div><p>20 日暖機、5 日標籤、4 段 walk-forward、5 日 gap；最後 20% 保留測試只評估一次。所有 scaler 僅在訓練區間擬合。</p><q-select outlined v-model="dataset" :options="datasetOptions" emit-value map-options label="研究資料版本"/><q-btn color="primary" label="啟動研究" :loading="busy" @click="startJob('research')"/><div class="hint">驗證平衡準確度 ≥ 52% 且高於基準 1 個百分點才可人工核准；不是交易勝率或獲利承諾。</div><div class="form-grid"><q-checkbox v-model="schedule.enabled" label="啟用批次排程（相同版本自動去重）"/><q-input outlined v-model.number="schedule.interval" type="number" label="排程間隔（秒，至少 60）"/></div><q-btn flat color="primary" label="儲存排程" @click="act(()=>api('/schedule',schedule))"/></section><section class="panel"><div class="panel-title"><h2>目前版本與候選比較</h2><q-btn flat label="恢復規則策略" @click="act(()=>api('/models/reset',{}))"/></div><p>目前版本：<strong>{{state.active_model||'MA5 / MA20 規則策略'}}</strong></p><div v-if="!state.models.length" class="empty">尚無候選模型；研究完成後會在此保存完整版本。</div><div v-for="m in state.models" :key="m.id" class="model-card"><div class="panel-title"><h3>{{m.id}} <span class="badge">{{m.report.eligible?'通過驗證門檻':'保留原策略'}}</span></h3><q-btn color="primary" label="人工核准至模擬環境" :disable="!m.report.eligible||state.active_model===m.id" @click="act(()=>api('/models/'+m.id+'/approve',{}))"/></div><div class="info-grid"><p><b>Walk-forward 平衡準確度</b>{{percent(m.report.score)}}</p><p><b>多數類別基準</b>{{percent(m.report.baseline)}}</p><p><b>保留測試（非選模依據）</b>{{percent(m.report.holdout_score)}}</p><p><b>資料漂移</b>{{m.report.drift_warning?'需檢查（不自動換模）':'未超過工程警戒值'}}</p></div><details><summary>版本、區間、缺漏率與研究限制</summary><pre>{{JSON.stringify(m.report,null,2)}}</pre></details></div></section></template>
 <section v-if="['回測實驗室','研究中心'].includes(page)" class="panel"><h2>可追蹤的工作紀錄</h2><div v-if="!state.jobs.length" class="empty">尚未建立工作</div><div v-for="j in state.jobs.filter((j:any)=>j.kind===(page==='研究中心'?'research':'backtest'))" :key="j.id" class="job-row"><div><strong>{{j.kind==='research'?'研究':'回測'}} · {{j.id.slice(0,8)}}</strong><small>{{time(j.created)}} · {{statusNames[j.status]}} · {{j.progress}}%</small><small v-if="j.error" class="text-negative">{{j.error}}</small></div><q-btn flat label="查看結果" @click="viewJob(j.id)"/></div><div v-if="result?.result?.skipped" class="hint">{{result.result.reason}}</div><div v-if="result?.status==='RUNNING'||result?.status==='QUEUED'" class="hint"><q-spinner size="20px"/> 工作進行中；由獨立程序執行，不阻塞風控。</div></section>
 <template v-if="page==='設定'"><section class="panel"><h2>模擬風控規則 v{{state.rules.version}}</h2><p class="muted">此介面僅允許維持或收緊初始曝險上限。比率以小數輸入；修改會保存新版本並寫入稽核。</p><div class="form-grid"><q-input v-for="(label,key) in {per_order:'單筆淨值比例 ≤ 0.05',per_symbol:'單一標的曝險 ≤ 0.15',total:'總曝險 ≤ 0.50',daily_loss:'單日損失門檻 ≤ 0.01',drawdown:'回撤門檻 ≤ 0.05',daily_proposals:'每日新風險提案上限',fee_rate:'手續費率（模擬假設）',min_fee:'最低手續費（模擬假設）',slippage:'滑價比例',participation:'成交量參與率'}" :key="key" outlined type="number" step="any" v-model.number="rules[key]" :label="label"/></div><q-btn color="primary" label="驗證並保存新規則版本" :loading="busy" @click="act(()=>api('/rules',rules),'規則已版本化保存')"/></section><section class="panel"><h2>模式與資料安全</h2><div class="info-grid"><p><b>DEMO</b>可重現合成行情。</p><p><b>REPLAY</b>依資料內明確日期重播。</p><p><b>PAPER</b>停用：尚無已驗證即時來源。</p><p><b>LIVE</b>停用：後端拒絕啟用，無真實券商串接。</p></div><q-btn disable label="LIVE 尚未開放"/><p class="hint">服務僅綁定 localhost；三角色為同一部主機上的程序隔離，不具有獨立主機或惡意管理者防護能力。</p><q-btn outline :label="state.session_open?'關閉模擬交易時段':'開啟模擬交易時段'" @click="control('session_open',!state.session_open)"/></section></template>
 </template>
 <footer>TradingLab <span>研究有紀錄，交易有邊界。</span><span>LOCAL-FIRST · REPRODUCIBLE · SIMULATION ONLY</span></footer></div></main>
 <q-dialog v-model="login" persistent><q-card class="login-card"><q-card-section><div class="eyebrow">LOCAL ACCESS</div><h2>連接你的研究工作區</h2><p>貼上啟動腳本顯示的本機存取權杖，或讀取專案內 <code>.local/client-token.txt</code>。權杖僅存於此分頁。</p><q-input outlined v-model="token" type="password" label="本機存取權杖" @keyup.enter="connect"/><div v-if="error" class="error">{{error}}</div></q-card-section><q-card-actions align="right"><q-btn color="primary" label="連接 TradingLab" @click="connect"/></q-card-actions></q-card></q-dialog>
</div>
</template>
